\begin{aligned}
\iint_{D} \frac{x y}{\sqrt{1+y^{3}}} d x d y&=\int_{0}^{1} d y \int_{-\sqrt{y}}^{0} \frac{x y}{\sqrt{1+y^{3}}} d x\\
&=\int_{0}^{1} \frac{y}{2 \sqrt{1+y^{3}}} \cdot x^{2}\bigg|_{-\sqrt{y}}^{0} d y=-\int_{0}^{1} \frac{y^{2}}{2 \sqrt{1+y^{3}}} d y\\
&=-\frac{1}{3} \sqrt{1+y^{3}}\bigg|_{0}^{1}=\frac{1-\sqrt{2}}{3}
\end{aligned}
$

