&=2\left[-\frac{1}{\sin \theta}-\frac{1}{3} \sin ^{3} \theta\right]_{\frac{\pi}{4}}^{\frac{\pi}{2}}=\frac{13 \sqrt{2}-16}{6}
\end{aligned}
$

