$
\begin{aligned}
\sum_{n=1}^{\infty}(3 n-1) x^{n}
&=3x\sum_{n=1}^{\infty}n x^{n-1}-\sum_{n=1}^{\infty}x^{n}\\
&=3x\left(\sum_{n=1}^{\infty}x^{n}\right)'-\sum_{n=1}^{\infty}x^{n}\\
&=3x\left(\frac{x}{1-x}\right)'-\frac{x}{1-x}\\
&=\frac{x^{2}+2x}{(1-x)^2}
\end{aligned}
$

$
\begin{aligned}
\lim _{x \to+\infty}\left(\sqrt{2 x^{2}+x+2}-\sqrt{2} x\right)&=\lim _{x \to+\infty} \frac{x+2}{\sqrt{2 x^{2}+x+2}+\sqrt{2} x} \\
&=\lim _{x \to+\infty} \frac{1+\frac{2}{x}}{\sqrt{2+\frac{1}{x}+\frac{2}{x^{2}}}+\sqrt{2}} \\
&=\frac{1}{2 \sqrt{2}}=\frac{\sqrt{2}}{4}
\end{aligned}
$

$
\begin{aligned}
\lim_{x\to 0}\left( \frac{1}{x}-\frac{\ln (1+x)}{x\sin x} \right)
&=\lim_{x\to 0}\frac{\sin x-\ln (1+x)}{x\sin x}\\
&=\lim _{x \to 0} \frac{\sin x-\ln (1+x)}{x^{2}}
=\lim _{x \to 0} \frac{\cos x-\frac{1}{1+x}}{2 x}\\
&=\lim _{x \to 0} \frac{-\sin x+\frac{1}{(1+x)^{2}}}{2}=\frac{1}{2}
\end{aligned}
$

